};

const isTokenRevoked = (token) => {
  return new Promise((resolve, reject) => {
    client.sismember('revokedTokens', token, (err, reply) => {
      if (err) {
        reject(err);
      } else {
        resolve(reply === 1);
      }
    });
  });
