    ports:
      - "4500:4500"
    depends_on:
      - redis
    environment:
      - REDIS_HOST=redis
      - REDIS_PORT=6379

  redis:
    image: redis:latest
    ports:
      - "6379:6379"
```

### Step 4: Dockerfile for the Node.js Application

