const AdminOnly = ({ children }) => {
  const { user } = useAuth();

  if (!user || user.role !== 'admin') {
    return <Navigate to="/unauthorized" />;
  }

  return children;
};

const ModeratorAndAdmin = ({ children }) => {
  const { user } = useAuth();

  if (!user || ![ 'admin', 'moderator' ].includes(user.role)) {
    return <Navigate to="/unauthorized" />;
  }

  return children;
};

