  }, [cookies]);

  const setUserFromToken = async (token) => {
    try {
      const response = await axios.get('/api/user', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      setUser(response.data.user);
    } catch (error) {
      console.error('Failed to fetch user data:', error);
      removeCookie('jwt');
      setUser(null);
    }
  };

  const fetchPermissions = async () => {
    try {
      const response = await axios.get('/api/permissions', {
        headers:  {
          Authorization: `Bearer ${cookies.jwt}`,
        },
      });
      setPermissions(response.data);
    } catch (error) {
      console.error('Failed to fetch permissions:', error);
    }
  };

  useEffect(() => {
    if (user) {
      fetchPermissions();
    }
  }, [user]);

  const login = async (username, password) => {
    try {
      const response = await axios.post('/api/login', { username, password });
      const token = response.data.token;
      setCookie('jwt', token, { path: '/', httpOnly: true, sameSite: 'strict' });
      setUserFromToken(token);
    } catch (error) {
      console.error('Login failed:', error);
    }
  };

  const logout = () => {
    removeCookie('jwt');
    setUser(null);
    setPermissions([]);
  };

  const refreshToken = async () => {
    if (isRefreshing) {
      return new Promise((resolve) => {
        const interval = setInterval(() => {
          if (!isRefreshing) {
            clearInterval(interval);
            resolve(cookies.jwt);
          }
        }, 100);
      });
    }

    setIsRefreshing(true);

    try {
      const response = await axios.post('/api/token-refresh', {}, {
        headers: {
          Authorization: `Bearer ${cookies.jwt}`,
        },
      });
      const newToken = response.data.token;
      setCookie('jwt', newToken, { path: '/', httpOnly: true, sameSite: 'strict' });
      setUserFromToken(newToken);
      return newToken;
    } catch (error) {
      setRefreshError(error);
      logout();
      throw error;
    } finally {
      setIsRefreshing(false);
    }
  };

  return { user, permissions, login, logout, refreshToken, isRefreshing, refreshError };
};

export default useAuth;
```

