  issuer: 'your-app-name',
  audience: 'your-app-audience',
  subject: 'user-id',
  expiresIn: '7d', // Refresh token expires in 7 days
  algorithm: 'RS256',
};

// Sign JWT
function signJwt(payload) {
  return jwt.sign(payload, privateKey, jwtOptions);
}

// Sign Refresh Token
function signRefreshJwt(payload) {
