const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
  console.log('Client connected');

  // Heartbeat mechanism
  const heartbeatInterval = 30000; // 30 seconds
  const heartbeatTimeout = 10000; // 10 seconds
  let heartbeatTimer;

  const sendHeartbeat = () => {
