// ChatController.js
class ChatController {
  async handleRequest(req, res) {
    try {
      // Line 88: Synchronous file system call
      const data = fs.readFileSync('path/to/file.txt', 'utf8');
      // Process data...
      res.send(data);
    } catch (error) {
      console.error(error);
      res.status(500).send('Internal Server Error');
    }
  }
}
```

