    const key = 'chatbot_data';
    const data = await getDataFromCacheOrDB(key, fetchDataFromDB);
    console.log('Data:', data);
  } catch (err) {
    console.error('Error:', err);
  } finally {
    client.quit();
  }
})();
```

### Explanation

